<?php
function officer_queues(){return [
 'blocked'=>['Blocked / waiting',"i.status='In Progress' AND i.maintenance_stage='Blocked'"],
 'returned'=>['Province returned',"i.status='In Progress' AND i.maintenance_stage='Officer Return'"],
 'open'=>['All open',"i.status NOT IN ('Resolved','Rejected','Duplicate')"],
 'needs_team'=>['Needs team',"i.status IN ('Assigned','In Progress') AND i.maintenance_id IS NULL"],
 'team_working'=>['Team working',"i.status IN ('Assigned','In Progress') AND i.maintenance_id IS NOT NULL AND i.maintenance_stage IN ('Assigned','In Progress','Returned')"],
 'review'=>['Needs my review',"i.status IN ('Assigned','In Progress') AND i.maintenance_stage='Review'"],
 'admin'=>['Awaiting admin',"i.status='Awaiting Approval'"],
 'closed'=>['Closed',"i.status IN ('Resolved','Rejected','Duplicate')"],
 'confirmation'=>['Needs admin confirmation',"i.status IN ('Submitted','Verified')"]
];}
function officer_counts(){
 $select=[];foreach(officer_queues() as $key=>$v)$select[]='COALESCE(SUM('.$v[1].'),0) `'.$key.'`';$select[]='COALESCE(SUM('.staff_overdue_sql().'),0) overdue';
 return q('SELECT '.implode(',',$select).' FROM issues i WHERE i.officer_id=?',[user()['id']])->fetch();
}
function officer_next($i){
 $url='index.php?page=issue&id='.(int)$i['id'];
 if(in_array($i['status'],['Submitted','Verified'],true))return ['View assignment',$url,'Admin confirmation needed'];
 if(in_array($i['status'],['Resolved','Rejected','Duplicate'],true))return ['View history',$url,'Closed'];
 if($i['status']==='Awaiting Approval')return ['View submission',$url,'Waiting for admin review'];
 if($i['maintenance_stage']==='Officer Return')return ['Review returned work',$url.'#workflow','Province Admin returned completion'];
 if($i['maintenance_stage']==='Blocked')return ['Review delay',$url.'#workflow','Team reported a blocker'];
 if($i['maintenance_stage']==='Review')return ['Review completion',$url.'#maintenance-work','Officer review needed'];
 if($i['maintenance_stage']==='Returned')return ['View returned work',$url.'#maintenance-work','Returned to team'];
 if(!$i['maintenance_id'])return ['Assign team',$url.'#maintenance-work','Choose a maintenance team'];
 return ['View progress',$url.'#maintenance-work',$i['maintenance_stage']==='Assigned'?'Team has not started':'Team working'];
}
function officer_table($rows){
 if(!$rows){?><div class="officer-empty"><span aria-hidden="true">✓</span><h3>No work in this selection</h3><p>Try another queue or reset the filters. New assignments appear here.</p><a class="button secondary" href="index.php?page=assigned">Show all open work</a></div><?php return;}
?><div class="table-wrap officer-work-table"><table><thead><tr><th>Report / area</th><th>Priority</th><th>Status</th><th>Maintenance team</th><th>Due / attention date</th><th>Next action</th></tr></thead><tbody><?php foreach($rows as $i):$action=officer_next($i);$closed=in_array($i['status'],['Resolved','Rejected','Duplicate'],true);$deadline=$i['due_date']?:date('Y-m-d',strtotime($i['created_at'].' +7 days'));$late=!$closed && strtotime($deadline.' 23:59:59')<time();?><tr><td data-label="Report"><a class="table-title" href="index.php?page=issue&amp;id=<?=$i['id']?>"><small>#<?=str_pad($i['id'],4,'0',STR_PAD_LEFT)?></small><?=e($i['title'])?></a><small class="muted"><?=e($i['area_name']?:'Area not specified')?> · <?=e($i['category'])?></small></td><td data-label="Priority"><span class="priority-chip p-<?=strtolower($i['priority'])?>"><?=e($i['priority'])?></span></td><td data-label="Status"><?=badge($i['status'])?><small class="muted"><?=e($action[2])?></small></td><td data-label="Team"><?=e($i['maintenance_team']?:'Not assigned')?><?php if($i['maintenance_id']):?><small class="muted"><?=e($i['maintenance_stage']==='Review'?'Completion submitted':$i['maintenance_stage'])?></small><?php endif;?></td><td data-label="Due date"><span class="<?=$late?'overdue-label':''?>"><?=e($deadline)?></span><small class="muted"><?=$i['due_date']?'Due date':'7-day attention date'?><?=$late?' · Overdue':''?></small></td><td data-label="Action"><a class="button <?=$action[0]==='Review completion'?'':'secondary'?> officer-row-action" href="<?=e($action[1])?>"><?=e($action[0])?> →</a></td></tr><?php endforeach;?></tbody></table></div><?php
}
function officer_pagination($pn,$max){?><nav class="pagination" aria-label="Work pages"><span>Page <?=$pn?> of <?=$max?></span><?php foreach([-1=>'← Previous',1=>'Next →'] as $d=>$label):if($pn+$d<1||$pn+$d>$max)continue;$query=$_GET;$query['p']=$pn+$d;?><a href="?<?=e(http_build_query($query))?>"><?=$label?></a><?php endforeach;?></nav><?php }
function officer_work_page($map=false){
 require_role('officer');$counts=officer_counts();$queues=officer_queues();$tab=(string)($_GET['tab']??'open');if(!isset($queues[$tab]))$tab='open';
 $search=trim(substr((string)($_GET['search']??''),0,160));$category=max(0,(int)($_GET['category']??0));$priority=(string)($_GET['priority']??'');$status=(string)($_GET['status']??'');$scope=($_GET['scope']??'mine')==='all'?'all':'mine';
 $where=[];$params=[];if(!$map||$scope==='mine'){$where[]='i.officer_id=?';$params[]=user()['id'];}
 if(!$map)$where[]='('.$queues[$tab][1].')';
 if($search!==''){$where[]='(i.title LIKE ? OR i.address LIKE ? OR i.id=?)';$params[]='%'.$search.'%';$params[]='%'.$search.'%';$params[]=(int)ltrim($search,'#');}
 if($category){$where[]='i.category_id=?';$params[]=$category;}
 if(in_array($priority,['Low','Medium','High'],true)){$where[]='i.priority=?';$params[]=$priority;}
 if(in_array($status,staff_statuses(),true)){$where[]='i.status=?';$params[]=$status;}
 $sort=(string)($_GET['sort']??'priority');$orders=['priority'=>"FIELD(i.priority,'High','Medium','Low'),i.created_at,i.id",'due'=>"COALESCE(i.due_date,DATE_ADD(DATE(i.created_at),INTERVAL 7 DAY)),i.id",'newest'=>'i.created_at DESC,i.id DESC'];if(!isset($orders[$sort]))$sort='priority';
 if(!$map && ($_GET['late']??'')==='1')$where[]=staff_overdue_sql();
 $sql=$where?' WHERE '.implode(' AND ',$where):'';$total=(int)q('SELECT COUNT(*) FROM issues i'.$sql,$params)->fetchColumn();$limit=$map?500:15;$max=max(1,(int)ceil($total/$limit));$pn=min($max,max(1,(int)($_GET['p']??1)));$rows=q(issue_query().$sql.' ORDER BY '.$orders[$sort].' LIMIT '.$limit.' OFFSET '.(($pn-1)*$limit),$params)->fetchAll();
 layout_start($map?'Community map':'Assigned to me',$map?'Locate work and plan site visits. Your assignments are selected by default.':'Your work queue · Delegate, monitor and review maintenance work.',$map);
?><div class="officer-workspace"><?php if(!$map):?><div class="officer-queue-heading"><span class="officer-total"><?=$counts['open']?> open assignments</span><a class="text-link" href="index.php?page=map">View on map ↗</a></div><nav class="officer-tabs" aria-label="Assignment stages"><?php foreach($queues as $key=>$q):if($key==='confirmation'&&!$counts[$key])continue;$query=$_GET;unset($query['status'],$query['p'],$query['late']);$query['page']='assigned';$query['tab']=$key;?><a class="<?=$tab===$key?'selected':''?>" href="?<?=e(http_build_query($query))?>" <?=$tab===$key?'aria-current="page"':''?>><?=e($q[0])?><b><?=$counts[$key]?></b></a><?php endforeach;?></nav><?php if($counts['confirmation']):?><div class="officer-notice"><strong><?=$counts['confirmation']?> assignment(s) need admin confirmation.</strong> These older reports have an officer but are still Submitted/Verified. An admin must confirm them in Assign issues before team work starts.</div><?php endif;?><?php endif;?>
<form class="panel officer-filter" method="get"><input type="hidden" name="page" value="<?=$map?'map':'assigned'?>"><?php if(!$map):?><input type="hidden" name="tab" value="<?=e($tab)?>"><?php if(($_GET['late']??'')==='1'):?><input type="hidden" name="late" value="1"><?php endif;?><?php endif;?><label class="officer-search">Search reports<input type="search" name="search" maxlength="160" value="<?=e($search)?>" placeholder="Title, location or #ID"></label><?php if($map):?><label>Show<select name="scope"><option value="mine" <?=$scope==='mine'?'selected':''?>>My assigned issues</option><option value="all" <?=$scope==='all'?'selected':''?>>All community issues</option></select></label><?php else:?><label>Priority<select name="priority"><option value="">All priorities</option><?php foreach(['High','Medium','Low'] as $v):?><option <?=$priority===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><?php endif;?><label>Category<select name="category"><option value="0">All categories</option><?php foreach(categories() as $c):?><option value="<?=$c['id']?>" <?=$category===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(staff_statuses() as $v):?><option <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><?php if(!$map):?><label>Sort<select name="sort"><?php foreach(['priority'=>'Priority first','due'=>'Due date','newest'=>'Newest first'] as $v=>$label):?><option value="<?=$v?>" <?=$sort===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><?php endif;?><div class="officer-filter-actions"><button class="button secondary">Apply</button><a class="text-link" href="index.php?page=<?=$map?'map':'assigned'?>">Reset</a></div></form>
<?php if($map):?><details class="officer-location-search"><summary>Find a place or street</summary><?php location_search('community-map');?></details><div class="officer-map-legend" aria-label="Map status colours"><?php foreach(officer_map_colours() as $label=>$colour):?><span><i style="background:<?=$colour?>"></i><?=e($label)?></span><?php endforeach;?></div><div id="community-map" class="officer-map" aria-label="Issue locations"></div><script type="application/json" id="map-data"><?=json_encode(array_map(function($i){return ['id'=>$i['id'],'title'=>$i['title'],'status'=>$i['status'],'latitude'=>$i['latitude'],'longitude'=>$i['longitude'],'color'=>officer_map_colours()[$i['status']]??'#526a75'];},$rows),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script><p class="small muted"><?=count($rows)?> of <?=$total?> matching reports shown · Map and Satellite modes remain available. Use filters or pages for more than 500 reports.</p><details class="panel officer-map-list"><summary>Report list (<?=count($rows)?>)</summary><?php issue_table($rows);?></details><?php else:?><div class="officer-list-heading"><h2><?=e($queues[$tab][0])?></h2><span class="small muted"><?=$total?> matching reports<?=($_GET['late']??'')==='1'?' · Overdue only':''?></span></div><section class="panel no-pad"><?php officer_table($rows);?></section><?php endif;?><?php officer_pagination($pn,$max);?></div><?php layout_end();
}
function officer_map_colours(){return ['Submitted'=>'#697887','Verified'=>'#247e86','Assigned'=>'#245ac5','In Progress'=>'#c27a15','Awaiting Approval'=>'#7b45ad','Resolved'=>'#21855a','Rejected'=>'#b84949','Duplicate'=>'#6a6578'];}
